create or replace function public.merge_external_location_metadata(p_location_id uuid,p_name text default null,p_address text default null,p_city text default null,p_state text default null,p_postal_code text default null,p_place_type text default null,p_source_dataset text default null,p_source_external_id text default null,p_source_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$ begin update public.locations set name=coalesce(nullif(name,''),p_name),address=coalesce(nullif(address,''),p_address),city=coalesce(nullif(city,''),p_city),state=coalesce(nullif(state,''),p_state),postal_code=coalesce(nullif(postal_code,''),p_postal_code),place_type=coalesce(nullif(place_type,''),p_place_type),source_dataset=coalesce(source_dataset,p_source_dataset),source_external_id=coalesce(source_external_id,p_source_external_id),source_metadata=coalesce(source_metadata,'{}'::jsonb) || coalesce(p_source_metadata,'{}'::jsonb),updated_at=now() where id=p_location_id; return p_location_id; end; $$;
